/* ===================== v8.1 — any-day release, streaming reports, logos, bidding, market, studio page, social, vault, world hub ===================== */
/* ---------- any-day release ---------- */
const DAYM={0:.62,1:.6,2:.66,3:1.06,4:1.02,5:1,6:.78};
const DAYL={0:'Sunday · opening misses most of the weekend',1:'Monday · weak, spread-thin opening',2:'Tuesday · weak, spread-thin opening',3:'Wednesday · 5-day opening',4:'Thursday · fan previews + weekend',5:'Friday · classic full weekend',6:'Saturday · misses Friday crowds'};
function wkNear(t,d){let best=0,bd=99;for(let k=0;k<4;k++){const f=dateOf(t,k,5).getDate();const dd=Math.abs(f-d);if(dd<bd){bd=dd;best=k}}return best}
applyHol=function(p){const h=p.relDate?holidaysIn(p.releaseT).find(x=>x.d===p.relDate):null;const y=START_YEAR+Math.floor(p.releaseT/12),m=p.releaseT%12;const dow=p.relDate?new Date(y,m,p.relDate).getDay():5;
 p.holBoost=(h?h.boost:1)*(DAYM[dow]||1);p.holL=h?h.l:(dow!==5?DAYL[dow].split(' · ')[0]+' release':null)};
function dateList(g,from,cur,action){const wiz=action.includes('W.releaseT');const pid=(action.match(/setDate\((\d+)/)||[])[1];const P=pid?S.projects.find(p=>p.id==pid):null;
 const selT=wiz?W.releaseT:P?P.releaseT:null,selD=wiz?W.relDate:P?P.relDate:null,selK=wiz?(W.relWk||0):P?(P.relWk||0):0;
 let h=`<p class="muted" style="font-size:12px;margin-bottom:6px">Tap any day. Gold = Fridays (best for most films) · 🎉 holidays · red dots = rival releases · ⚔️ = rival tentpole.</p>`;
 for(let t=from;t<from+24;t++){const y=START_YEAR+Math.floor(t/12),m=t%12;const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();const fit=CAL[m].mult*(CAL[m].g[g]||1);const hs=holidaysIn(t);const riv=rivalsAt(t);
  let grid='<div class="cgrid pick any">'+DOW.map(d=>`<b>${d[0]}</b>`).join('');for(let i=0;i<first;i++)grid+='<span></span>';
  for(let d=1;d<=days;d++){const dow=new Date(y,m,d).getDay();const hol=hs.find(x=>x.d===d);const k=wkNear(t,d);
   const onDay=riv.filter(r=>relD(r).getDate()===d);const clash=onDay.some(r=>r.hype>85&&!r.lim&&!r.str);const sel=selT===t&&(selD?selD===d:(dow===5&&k===selK));
   const act=wiz?`pickRel(${t},${k},${d})`:`pickRelP(${pid},${t},${k},${d})`;
   grid+=`<span class="ok ${dow===5?'fri':''} ${hol?'hol':''} ${sel?'sel':''} ${clash?'clash':''}" onclick="${act}">${hol?'🎉':''}${d}${onDay.length?`<i>${clash?'⚔️':onDay.length}</i>`:''}</span>`}
  grid+='</div>';const cf=compFactor(t);let selInfo='';
  if(selT===t){const dd=selD||dateOf(t,selK,5).getDate();const dow=new Date(y,m,dd).getDay();const hol=hs.find(x=>x.d===dd);const mult=(DAYM[dow]||1)*(hol?hol.boost:1);
   selInfo=`<div class="dayinfo"><b>${DOW[dow]} ${dd} ${MON[m]}</b> · ${DAYL[dow].split(' · ')[1]}${hol?' · '+hol.l:''} <span class="${mult>=1?'pos':'neg'}">${mult>=1?'+':''}${Math.round((mult-1)*100)}% opening</span></div><div class="muted" style="font-size:12px">${riv.length?riv.map(r=>`${GEN[r.g].icon} ${esc(r.title)} · ${fmtDay(relD(r))} · ${esc(r.studio.split(' ')[0])}${r.hype>85?' ⚠️':''}`).join('<br>'):'No rival releases this month.'}</div>`}
  h+=`<div class="card ${selT===t?'sel':''}"><div class="row"><b>${tLabel(t)}</b><span class="tag ${fit>=1.2?'hot':fit<.85?'bad':''}">${fit>=1.2?'🔥 Great fit':fit<.85?'Weak fit':'OK fit'} ×${fit.toFixed(2)}</span></div><div class="muted" style="font-size:12px">${CAL[m].tag} · competition ${cf>1.05?'light':cf<.8?'brutal':cf<.92?'crowded':'normal'}${hs.length?' · '+hs.map(x=>x.l).join(', '):''}</div>${grid}${selInfo}</div>`}
 return h}

/* ---------- streaming performance ---------- */
const ST_TH=[9,6.5,4.8,3.6,2.8,2.2,1.7,1.3,1,.75];
function stRank(v){const s=v/inf(tNow())*inf(0);for(let i=0;i<10;i++)if(s>=ST_TH[i])return i+1;return 99}
function streamInit(f){if(f.sv)return;const base=f.views||+(clamp(f.critic*.4+f.aud*.4,10,99)/6*R(.6,1.4)).toFixed(1);const w0=Math.max(.6,base*.42);const sv=[];let c=w0;
 for(let i=0;i<20&&(i<3||c>.4);i++){sv.push(+c.toFixed(2));c*=clamp(.55+(f.aud-50)/250+R(-.05,.05),.4,.85)}f.sv=sv;f.sShown=1;f.comp=Math.round(clamp(f.aud*.85+R(-6,8),22,96));
 f.subsG=f.dist==='stream'&&S.streaming?+(sum(sv,x=>x)*.035).toFixed(2):0;const pool=['USA','UK','India','Brazil','Mexico','South Korea','Japan','Germany','France','Spain'];f.sCountries=shuffle(pool).slice(0,RI(3,6));f.sOut=f.dist==='sell'?(f.buyer||pick([TECH_STREAMER.n].concat(S.rivals.filter(r=>r.svc).map(r=>r.svc)))):(S.streaming?S.streaming.name:'streaming')}
function streamFilmTick(){const lines=[];S.films.forEach(f=>{if(f.dist!=='stream'&&f.dist!=='sell')return;if(f.sDone)return;if(f.sv===undefined&&f.sShown===undefined){if(filmK(f)>12){f.sDone=1;return}}
 streamInit(f);const k=filmK(f);if(k<=0||k+1<=f.sShown)return;if(k<f.sv.length){f.sShown=k+1;const v=f.sv[k];const rk=stRank(v);lines.push({sf:f,k,v,rk});if(f.subsG&&S.streaming){S.streaming.subs+=f.subsG/f.sv.length}}
 else{f.sDone=1;const best=Math.min(...f.sv.map(stRank));const wk=f.sv.filter(v=>stRank(v)<=10).length;lines.push({sf:f,end:1,best,wk});addNews(`📺 <b>${esc(f.title)}</b> finishes its streaming run: ${fmtC(sum(f.sv,x=>x)*1e6)} views${best<=10?`, peaked at #${best}, ${wk} weeks in the top 10`:''}.`);
  if(f.terms&&f.terms.bonus&&best<=3){const b=+(f.revenue*.25).toFixed(1);S.cash+=b;addNews(`💰 Top-10 bonus: ${esc(f.sOut)} pays ${M(b)} extra for <b>${esc(f.title)}</b>.`)}}});
 if(lines.length){if(!WKREP.length&&!QUEUE.includes(showWeekRep))QUEUE.push(showWeekRep);WKREP=WKREP.concat(lines)}}
const _swr81=showWeekRep;showWeekRep=function(){const st=WKREP.filter(x=>x.sf);WKREP=WKREP.filter(x=>!x.sf);if(!st.length)return _swr81();
 const html=st.map(x=>x.end?`<div class="card mine"><div class="pcard">${posterSVG(x.sf,46)}<div style="flex:1"><b>📺 ${esc(x.sf.title)} — streaming run over</b><div class="muted" style="font-size:13px">${fmtC(sum(x.sf.sv,v=>v)*1e6)} views · ${x.best<=10?'peak #'+x.best+' · '+x.wk+' wks in top 10':'never reached the top 10'}</div></div></div></div>`:
  `<div class="card"><div class="pcard">${posterSVG(x.sf,46)}<div style="flex:1"><b>${esc(x.sf.title)} · streaming week ${x.k+1}</b><div class="row" style="font-size:14px;margin-top:4px"><span>${esc(x.sf.sOut)}</span><b>${fmtC(x.v*1e6)} views</b></div><div class="row" style="font-size:12px"><span class="${x.rk<=10?'pos':'muted'}">${x.rk<=10?'#'+x.rk+' in Movies this week':'Outside the top 10'}</span><span class="muted">${x.sf.comp}% finish it</span></div></div></div></div>`).join('');
 if(!WKREP.length){TAB='hq';render();modal(`<h3>📺 Streaming report</h3>${html}<button class="btn gold" onclick="modal();runQueue()">Continue</button>`);return}
 _swr81();const box=document.querySelector('#modal .modal>div');if(box&&box.insertAdjacentHTML)box.insertAdjacentHTML('afterbegin',html)};
function streamSection(f){streamInit(f);const n=f.sDone?f.sv.length:Math.max(1,f.sShown||1);const sv=f.sv.slice(0,n);const mx=Math.max(...sv,1);const tot=sum(sv,x=>x);const best=Math.min(...sv.map(stRank));
 return `<div class="bohero"><div class="dark"><small>${f.sDone?'Total views':'Views so far'}</small><b>${fmtC(tot*1e6)}</b><span>${fmtC(tot*1e6*1.9)} hours watched</span></div><div><small>Best rank</small><b>${best<=10?'#'+best:'—'}</b><span>${f.sDone?'Run complete':'Week '+n+' on '+esc(f.sOut)}</span></div></div>
 <div class="card"><small>Weekly views</small><div class="sbars">${sv.map((v,i)=>`<div><i style="height:${Math.max(4,v/mx*100)}%;background:${stRank(v)<=10?'var(--gold2)':'var(--soft)'}"></i><span>${stRank(v)<=10?'#'+stRank(v):''}</span><small>W${i+1}</small></div>`).join('')}</div>
 <div class="kv"><span>Completion rate</span><b>${f.comp}%</b></div>${f.subsG?`<div class="kv"><span>New subscribers</span><b>+${(f.subsG*(n/f.sv.length)).toFixed(2)}M</b></div>`:''}<div class="kv"><span>Trending in</span><b>${f.sCountries.join(', ')}</b></div>${f.terms?`<div class="kv"><span>Deal terms</span><b>${[f.terms.window?'Cinema window':'',f.terms.bonus?'Top-10 bonus':'',f.terms.sequel?'You keep sequel rights':'Streamer owns sequels'].filter(Boolean).join(' · ')}</b></div>`:''}</div>`}
const _fr81=filmReport;filmReport=function(f,ctx){let h=_fr81(f,ctx);if(f.dist==='stream'||f.dist==='sell'){const i=h.indexOf('<div class="scores">');h=i>0?h.slice(0,i)+streamSection(f)+h.slice(i):h+streamSection(f)}return h};

