 eagle:'<path d="M12 8c-3-4-7-4-10-3 3 1 5 3 6 6l4 2 4-2c1-3 3-5 6-6-3-1-7-1-10 3z"/><path d="M10 13l2 7 2-7"/>',comet:'<circle cx="17" cy="7" r="3"/><path d="M15 9L3 21M14 6L5 15M18 10L9 19"/>',
