settings=(function(o){return function(){o();const box=document.querySelector('#modal .modal>div .card');if(box&&box.insertAdjacentHTML)box.insertAdjacentHTML('beforeend',`<div class="row" style="margin-top:12px"><span>🎨 Studio logo</span><button class="btn sm ghost" style="margin:0" onclick="logoDesigner()">Edit</button></div>`)}})(settings);

statusBadge=(function(o){return function(p){return p.vault?'<span class="stbadge" style="--c:#555">🔒 In the vault</span>':o(p)}})(statusBadge);
tLabel=(function(o){return function(t){return t>=90000?'In the vault':o(t)}})(tLabel);
